var fs = require('fs');
var json = fs.readFileSync('/tmp/pcfg.json', 'utf8');
var lines = json.split('\n');

// Try parsing with progressively more lines
for (var i = 1; i <= lines.length; i++) {
  var partial = lines.slice(0, i).join('\n');
  try {
    JSON.parse(partial);
  } catch(e) {
    // Only report if this is the FIRST failure
    // (many lines will fail because they're incomplete JSON)
    // We want the line where the error message changes from "unexpected end" to something else
    if (e.message.indexOf('Unexpected end') === -1 && e.message.indexOf('Expected property') === -1) {
      console.log('Line', i, ':', e.message.substring(0, 80));
      console.log('  Content:', lines[i-1].substring(0, 120));
      if (i > 1) console.log('  Prev:', lines[i-2].substring(0, 120));
      break;
    }
  }
}
